HISTORICAL_CONTRACTS = '# ruff: noqa: E402\nfrom module.config import server as _test_server\n\n_test_server.set_lang("global_cn")\n\nfrom tasks.base.resource_bar import (\n    RESOURCE_BAR_LAYOUT_COMBAT,\n    RESOURCE_BAR_LAYOUT_ARENA_BATTLE_PASS,\n    RESOURCE_BAR_LAYOUT_MAIN,\n    RESOURCE_BAR_LAYOUT_SECRET_SHOP,\n    ResourceBarCandidate,\n    expand_resource_bar_candidates,\n    merge_resource_bar_candidates,\n    normalize_resource_bar_text,\n    parse_resource_bar_candidates,\n)\n\n\ndef test_normalize_resource_bar_text():\n    assert normalize_resource_bar_text(" 16,425 ") == "16425"\n    assert normalize_resource_bar_text("145／5") == "145/5"\n    assert normalize_resource_bar_text("I6,O25") == "16025"\n    assert normalize_resource_bar_text("$237/360") == "$237/360"\n\n\ndef test_merge_resource_bar_candidates_split_digits():\n    candidates = [\n        ResourceBarCandidate(box=(10, 0, 30, 20), text="16"),\n        ResourceBarCandidate(box=(32, 0, 60, 20), text="425"),\n        ResourceBarCandidate(box=(120, 0, 150, 20), text="902"),\n    ]\n\n    merged = merge_resource_bar_candidates(candidates, expected_count=2, max_gap=8)\n\n    assert merged is not None\n    assert [candidate.text for candidate in merged] == ["16425", "902"]\n\n\ndef test_expand_resource_bar_candidates_combined_counters():\n    candidates = [\n        ResourceBarCandidate(box=(10, 0, 130, 20), text="318/5$237/360"),\n        ResourceBarCandidate(box=(160, 0, 200, 20), text="15504"),\n    ]\n\n    expanded = expand_resource_bar_candidates(candidates)\n\n    assert [candidate.text for candidate in expanded] == ["318/5", "237/360", "15504"]\n\n\ndef test_parse_secret_shop_layout():\n    candidates = [\n        ResourceBarCandidate(box=(10, 0, 40, 20), text="16425"),\n        ResourceBarCandidate(box=(120, 0, 150, 20), text="902"),\n    ]\n\n    parsed = parse_resource_bar_candidates(candidates, RESOURCE_BAR_LAYOUT_SECRET_SHOP)\n\n    assert parsed is not None\n    assert parsed["gold"].value == 16425\n    assert parsed["skystone"].value == 902\n\n\ndef test_parse_main_layout_counter():\n    candidates = [\n        ResourceBarCandidate(box=(10, 0, 200, 20), text="145/5$1611/360"),\n        ResourceBarCandidate(box=(260, 0, 300, 20), text="902"),\n    ]\n\n    parsed = parse_resource_bar_candidates(candidates, RESOURCE_BAR_LAYOUT_MAIN)\n\n    assert parsed is not None\n    assert parsed["arena_flag"].value == 145\n    assert parsed["arena_flag"].total == 5\n    assert parsed["stamina"].value == 1611\n    assert parsed["stamina"].total == 360\n    assert parsed["skystone"].value == 902\n\n\ndef test_parse_combat_layout_counter_first():\n    candidates = [\n        ResourceBarCandidate(box=(10, 0, 70, 20), text="$237/360"),\n        ResourceBarCandidate(box=(120, 0, 200, 20), text="119367861"),\n        ResourceBarCandidate(box=(260, 0, 320, 20), text="15504"),\n    ]\n\n    parsed = parse_resource_bar_candidates(candidates, RESOURCE_BAR_LAYOUT_COMBAT)\n\n    assert parsed is not None\n    assert parsed["stamina"].value == 237\n    assert parsed["stamina"].total == 360\n    assert parsed["gold"].value == 119367861\n    assert parsed["skystone"].value == 15504\n\n\ndef test_parse_combat_layout_trim_leading_icon_digit():\n    candidates = [\n        ResourceBarCandidate(box=(686, 0, 760, 20), text="5248/360"),\n        ResourceBarCandidate(box=(780, 0, 860, 20), text="119367861"),\n        ResourceBarCandidate(box=(900, 0, 960, 20), text="15504"),\n    ]\n\n    parsed = parse_resource_bar_candidates(candidates, RESOURCE_BAR_LAYOUT_COMBAT)\n\n    assert parsed is not None\n    assert parsed["stamina"].value == 248\n    assert parsed["stamina"].total == 360\n\n\ndef test_parse_combat_layout_keep_real_large_stamina_when_no_icon_overlap():\n    candidates = [\n        ResourceBarCandidate(box=(705, 0, 790, 20), text="5248/360"),\n        ResourceBarCandidate(box=(800, 0, 880, 20), text="119367861"),\n        ResourceBarCandidate(box=(900, 0, 960, 20), text="15504"),\n    ]\n\n    parsed = parse_resource_bar_candidates(candidates, RESOURCE_BAR_LAYOUT_COMBAT)\n\n    assert parsed is not None\n    assert parsed["stamina"].value == 5248\n    assert parsed["stamina"].total == 360\n\n\ndef test_parse_arena_battle_pass_layout():\n    candidates = [\n        ResourceBarCandidate(box=(10, 0, 60, 20), text="318/5"),\n        ResourceBarCandidate(box=(90, 0, 130, 20), text="12"),\n        ResourceBarCandidate(box=(160, 0, 190, 20), text="345678"),\n        ResourceBarCandidate(box=(240, 0, 270, 20), text="950"),\n    ]\n\n    parsed = parse_resource_bar_candidates(candidates, RESOURCE_BAR_LAYOUT_ARENA_BATTLE_PASS)\n\n    assert parsed is not None\n    assert parsed["arena_flag"].value == 318\n    assert parsed["arena_flag"].total == 5\n    assert parsed["conquest_point"].value == 12\n    assert parsed["gold"].value == 345678\n    assert parsed["skystone"].value == 950\n\n\nimport unittest\n\nclass LegacyRuleTests(unittest.TestCase):\n    def test_normalize_resource_bar_text(self):\n        test_normalize_resource_bar_text()\n\n    def test_merge_resource_bar_candidates_split_digits(self):\n        test_merge_resource_bar_candidates_split_digits()\n\n    def test_expand_resource_bar_candidates_combined_counters(self):\n        test_expand_resource_bar_candidates_combined_counters()\n\n    def test_parse_secret_shop_layout(self):\n        test_parse_secret_shop_layout()\n\n    def test_parse_main_layout_counter(self):\n        test_parse_main_layout_counter()\n\n    def test_parse_combat_layout_counter_first(self):\n        test_parse_combat_layout_counter_first()\n\n    def test_parse_combat_layout_trim_leading_icon_digit(self):\n        test_parse_combat_layout_trim_leading_icon_digit()\n\n    def test_parse_combat_layout_keep_real_large_stamina_when_no_icon_overlap(self):\n        test_parse_combat_layout_keep_real_large_stamina_when_no_icon_overlap()\n\n    def test_parse_arena_battle_pass_layout(self):\n        test_parse_arena_battle_pass_layout()\n'
